(* [comment removed for export] *)
Definition lowk1 (j c : Z) : Z := Z.land c (Z.ones j).
Definition lowk0 (j c : Z) : Z := Z.lxor (Z.ones j) (lowk1 j c).
Lemma lowk_gam : forall j c w, 0 <= j -> w mod 2 ^ j = c mod 2 ^ j ->
