Definition a_xor (A B : av) : option av :=
  reduce 0 ones64 (Z.lor (Z.land (ak0 A) (ak0 B)) (Z.land (ak1 A) (ak1 B)))
                  (Z.lor (Z.land (ak1 A) (ak0 B)) (Z.land (ak0 A) (ak1 B))).
